using System.Buffers.Binary;
using YoutubeDl.Engine;
using YoutubeDl.Engine.Media;

internal static class HdrReconstructChecks
{
    internal static LiveDashSelectionPolicy Policy=>HdrTransformChecks.Policy with{TransitionColorPolicy="hdr-reconstruct"};
    internal static IEnumerable<(string Name,Func<Task> Test)> All=>new[]{"valid","crop","crop-policy","crop-negative","crop-count","crop-overflow","crop-text","codec","disabled","peak"}.Select(m=>("HDR reconstruction policy "+m,(Func<Task>)(()=>PolicyCase(m))))
        .Concat(new[]{"identity","reflection","vertical","shear","crop","pixel-crop","crop-all","perspective","singular","bounds","aspect","area-reflect","area-crop","area-shear","inset-shear"}.Select(m=>("HDR reconstruction affine "+m,(Func<Task>)(()=>Affine(m)))))
        .Concat(new[]{"black","white","average","maxima","quantiles","peak","clip","nan","infinity","length","cancel","payload","reserved","windows"}.Select(m=>("HDR reconstruction histogram "+m,(Func<Task>)(()=>Histogram(m)))))
        .Concat(new[]{"parse","positive","negative","zero","clip-high","clip-low","threshold","polynomial","mmr","raster","half","rpu","crc","short","profile","mel","dimensions"}.Select(m=>("HDR reconstruction FEL "+m,(Func<Task>)(()=>Fel(m)))));
    private static void Check(bool condition,string message)=>WriteCleanupChecks.Check(condition,message);
    private static Task PolicyCase(string mode)
    {
        var p=mode switch{"crop"=>Policy with{TransitionCrop="2,4,6,8"},"crop-policy"=>Policy with{TransitionColorPolicy="hdr-transform",TransitionCrop="0,0,0,0"},"crop-negative"=>Policy with{TransitionCrop="-1,0,0,0"},"crop-count"=>Policy with{TransitionCrop="1,2"},"crop-overflow"=>Policy with{TransitionCrop="999999999999999999,0,0,0"},"crop-text"=>Policy with{TransitionCrop="left,top,right,bottom"},"codec"=>Policy with{TransitionVideoCodec="av1"},"disabled"=>Policy with{NormalizeTransitions=false},"peak"=>Policy with{HdrPeakNits=1000},_=>Policy};try{p.Validate();Check(mode is "valid" or "crop","Invalid reconstruction policy succeeded.");}catch(ArgumentException)when(mode is not ("valid" or "crop")){}return Task.CompletedTask;
    }
    internal static string Matrix(double a,double b,double c,double d,int perspective=0)=>$"00000000: {(int)Math.Round(a*65536)} {(int)Math.Round(c*65536)} {perspective}\n00000001: {(int)Math.Round(b*65536)} {(int)Math.Round(d*65536)} 0\n00000002: 0 0 1073741824\n";
    private static Task Affine(string mode)
    {
        var invalid=mode is "crop-all" or "singular" or "bounds" or "aspect" or "inset-shear";try
        {
            var matrix=mode is "reflection" or "area-reflect"?Matrix(-1,0,0,1):mode=="vertical"?Matrix(1,0,0,-1):mode is "shear" or "area-shear" or "inset-shear"?Matrix(1,.5,0,1):mode=="perspective"?Matrix(1,0,0,1,1):mode=="singular"?Matrix(1,1,1,1):null;var crop=mode is "crop" or "pixel-crop" or "area-crop"?"1,1,1,1":mode=="crop-all"?"4,0,0,0":null;var g=HdrAffineCanvas.Create(mode=="bounds"?8000:4,4,4,4,mode=="aspect"?"0:1":"1:1",matrix,crop);var source=new byte[4*4*6];for(var i=0;i<16;i++){BinaryPrimitives.WriteUInt16LittleEndian(source.AsSpan(i*2),(ushort)(100+i));BinaryPrimitives.WriteUInt16LittleEndian(source.AsSpan((16+i)*2),512);BinaryPrimitives.WriteUInt16LittleEndian(source.AsSpan((32+i)*2),512);}var result=new byte[source.Length];g.Render(source,result);
            if(mode=="identity")Check(source.SequenceEqual(result),"Identity affine processing changed samples.");if(mode=="reflection")Check(BinaryPrimitives.ReadUInt16LittleEndian(result)==103&&BinaryPrimitives.ReadUInt16LittleEndian(result.AsSpan(6))==100,"Reflection did not reverse horizontal samples.");if(mode=="vertical")Check(BinaryPrimitives.ReadUInt16LittleEndian(result)==112,"Vertical reflection did not reverse rows.");if(mode=="pixel-crop")Check(BinaryPrimitives.ReadUInt16LittleEndian(result)==105&&BinaryPrimitives.ReadUInt16LittleEndian(result.AsSpan(30))==110,"Crop sampled removed border pixels.");if(mode=="shear")Check(Math.Abs(g.Point(4,4).X-4)<1e-8&&BinaryPrimitives.ReadUInt16LittleEndian(result)==64,"Shear geometry or black fill differs.");if(mode=="area-reflect")Check(g.ActiveArea(1,0,0,0)==(0,1,0,0),"Reflection did not exchange active-area sides.");if(mode=="area-crop")Check(g.ActiveArea(0,0,0,0)==(0,0,0,0),"Crop did not trim active-area borders.");if(mode=="area-shear")Check(g.ActiveArea(0,0,0,0).Left==0,"Full active-area envelope changed.");if(mode=="inset-shear")g.ActiveArea(1,0,0,0);Check(!invalid,"Invalid affine transform succeeded.");
        }
        catch(Exception e)when(invalid&&e is InvalidDataException or NotSupportedException){return Task.CompletedTask;}Check(!invalid,"Invalid affine transform was accepted.");return Task.CompletedTask;
    }
    internal static byte[] FloatRaster(params float[] values){var bytes=new byte[values.Length*12];for(var c=0;c<3;c++)for(var i=0;i<values.Length;i++)BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan((c*values.Length+i)*4),BitConverter.SingleToInt32Bits(values[i]));return bytes;}
    private static Task Histogram(string mode)
    {
        var invalid=mode is "nan" or "infinity" or "length" or "cancel" or "windows";try
        {
            var values=mode=="black"?new float[]{0,0,0}:mode=="white"?new float[]{1,1,1}:mode=="nan"?new float[]{float.NaN}:mode=="infinity"?new float[]{float.PositiveInfinity}:mode=="clip"?new float[]{-1,2}:new float[]{.25f,.5f,.75f};var bytes=FloatRaster(values);if(mode=="length")bytes=bytes[..^1];using var cancel=new CancellationTokenSource();if(mode=="cancel")cancel.Cancel();var stats=HdrPixelHistogram.Measure(bytes,values.Length,cancel.Token);
            if(mode=="black")Check(stats.Average==0&&stats.Bright==1000&&stats.Quantile(100)==0,"All-black histogram was not exact.");if(mode=="white")Check(stats.Average==100000&&stats.Bright==1000&&stats.Quantile(1)==100000,"All-white normalization differs.");if(mode=="average")Check(stats.Average==50000,"Measured average changed.");if(mode=="maxima")Check(stats.MaxScl.SequenceEqual(new[]{75000,75000,75000}),"Component maxima changed.");if(mode=="quantiles")Check(stats.Quantile(33)==25000&&stats.Quantile(66)==50000&&stats.Quantile(100)==75000,"Nearest-rank quantiles changed.");if(mode=="peak")Check(stats.Bright==333,"Peak-bin occupancy changed.");if(mode=="clip")Check(stats.Average==50000&&stats.MaxScl[0]==100000,"Out-of-gamut sample normalization changed.");
            if(mode is "payload" or "windows"){var input=mode=="windows"?HdrSpatialChecks.PlusPayload(2,128,96):HdrTransformChecks.Payload();var mapped=HdrPlusHistogram.Regenerate(input,stats);var bits=new HdrBits(mapped);bits.Skip(86);Check(bits.Read(17)==75000&&bits.Read(17)==75000&&bits.Read(17)==75000&&bits.Read(17)==50000&&bits.Read(4)==3&&bits.Read(7)==33&&bits.Read(17)==25000,"Serialized measured HDR statistics differ.");}
            if(mode=="reserved"){var b=new HdrBits(HdrSpatialChecks.PlusPayload(1,128,96));var o=new HdrBits();o.Data.AddRange(b.Data.Take(86));for(var c=0;c<3;c++)o.Put(100000,17);o.Put(50000,17);o.Put(9,4);foreach(var p in new[]{1,5,10,25,50,75,90,95,99}){o.Put(p,7);o.Put(p==5?0:p==10?255:50000,17);}o.Put(100,10);o.Put(0,1);o.Put(0,2);o.Align();var mapped=new HdrBits(HdrPlusHistogram.Regenerate(o.Bytes(),stats));mapped.Skip(86+51+17+4+24);Check(mapped.Read(7)==5&&mapped.Read(17)==0&&mapped.Read(7)==10&&mapped.Read(17)==255,"Reserved HDR10+ percentile fields changed.");}Check(!invalid,"Invalid histogram request succeeded.");
        }
        catch(Exception e)when(invalid&&e is InvalidDataException or NotSupportedException or OperationCanceledException){return Task.CompletedTask;}Check(!invalid,"Invalid measured histogram was accepted.");return Task.CompletedTask;
    }
    private static Task Fel(string mode)
    {
        var invalid=mode is "crc" or "short" or "profile" or "dimensions";try
        {
            var nal=mode=="mel"?HdrTransformChecks.Mel:mode=="profile"?HdrSpatialChecks.Nal(DolbyMetadataFixtures.Profile8):HdrReconstructFixtures.Fel;if(mode=="crc")nal[^3]^=1;if(mode=="short")nal=nal[..8];var program=DolbyFelProgram.Read(nal);var expected=mode switch{"positive"=>.5+16d/4096,"negative"=>.5-16d/4096,_=>.5};var el=mode switch{"positive"=>528,"negative"=>496,"clip-high"=>1023,"clip-low"=>0,_=>512};if(mode is "positive" or "negative" or "zero")Check(Math.Abs(program.Compose(0,.5,.5,.5,el)-expected)<1e-12,"FEL signed residual composition differs.");if(mode=="clip-high")Check(program.Compose(0,1,1,1,1023)==1,"FEL high clipping failed.");if(mode=="clip-low")Check(program.Compose(0,0,0,0,0)==0,"FEL low clipping failed.");if(mode=="threshold"){var n=program with{Nlq=[new(512,1,.01,.02),program.Nlq[1],program.Nlq[2]]};Check(Math.Abs(n.Compose(0,.5,.5,.5,513)-.525)<1e-12&&n.Compose(0,.5,.5,.5,512)==.5,"FEL deadzone half-step or zero carve-out changed.");}
            if(mode is "polynomial" or "mmr"){var curve=mode=="polynomial"?new DolbyFelCurve([0,1],[new(0,2,[.1,.2,.3])]):new DolbyFelCurve([0,1],[new(1,1,[.1,.2,.3,.4,.5,.6,.7,.8])]);var n=program with{Curves=[curve,curve,curve],Nlq=[new(512,1,0,0),new(512,1,0,0),new(512,1,0,0)]};Check(Math.Abs(n.Compose(0,.2,.3,.4,512)-(mode=="polynomial"?.152:.1+.04+.09+.16+.03+.048+.084+.0192))<1e-12,"FEL polynomial/MMR prediction changed.");}
            if(mode is "raster" or "half" or "dimensions"){var b=new byte[4*4*6];for(var i=0;i<48;i++)BinaryPrimitives.WriteUInt16LittleEndian(b.AsSpan(i*2),512);var e=new byte[(mode=="half"?2*2:4*4)*6];for(var i=0;i<e.Length/2;i++)BinaryPrimitives.WriteUInt16LittleEndian(e.AsSpan(i*2),528);var o=new byte[b.Length];program.Reconstruct(b,e,o,4,4,mode=="half"?2:mode=="dimensions"?3:4,mode=="half"?2:4,default);Check(BinaryPrimitives.ReadUInt16LittleEndian(o)==2065,"FEL twelve-bit reconstruction changed.");}
            if(mode=="parse"){var shaped=DolbyFelProgram.Read(HdrReconstructFixtures.FelReshaped);Check(Math.Abs(shaped.Compose(0,.5,.5,.5,512)-.5625)<1e-12&&shaped.SingleLayerRpu.SequenceEqual(program.SingleLayerRpu),"FEL baking failed to replace applied reshaping with identity metadata.");}if(mode=="mmr"){var co=new double[22];co[0]=.1;co[1]=.2;co[8]=.3;co[15]=.4;var curve=new DolbyFelCurve([0,1],[new(1,3,co)]);var n=program with{Curves=[curve,curve,curve],Nlq=[new(512,1,0,0),new(512,1,0,0),new(512,1,0,0)]};Check(Math.Abs(n.Compose(0,.2,.3,.4,512)-.1552)<1e-12,"Higher-order FEL MMR terms changed.");}if(mode=="rpu")Check(DolbySpatialRpu.Area(program.SingleLayerRpu)==DolbySpatialRpu.Area(HdrSpatialChecks.Nal(DolbyMetadataFixtures.Profile8)),"Baked FEL metadata changed active areas.");if(mode=="mel")Check(Math.Abs(program.Compose(0,.5,.5,.5,800)-.5)<1e-12,"Neutral MEL gained residuals.");Check(!invalid,"Invalid FEL program succeeded.");
        }
        catch(Exception e)when(invalid&&e is InvalidDataException or NotSupportedException){return Task.CompletedTask;}Check(!invalid,"Invalid FEL program was accepted.");return Task.CompletedTask;
    }
}
